//! ESC guideline family previews, source rights notices and independently gated journal articles.
use super::pmc_crosswalk::{self as cw,Lookup,Planned,SourceRef};
use super::{common,Adapter,PlanRow};
use crate::guidelines::doc::{GuidelineDoc,Rights};
use crate::guidelines::fetch::Fetcher;
use crate::guidelines::html::{blocks_from_html,sel,text_of};
use crate::guidelines::registry::SourceEntry;
use anyhow::{bail,Context,Result};
use scraper::Html;
use serde_json::json;
use std::collections::HashSet;
use url::Url;
pub struct Esc;
const ROOT:&str="https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/";
fn catalog(raw:&str,base:&Url)->Result<Vec<(String,String)>>{let d=Html::parse_document(raw);let root=d.select(&sel("main")).next().context("ESC catalog main missing")?;let mut seen=HashSet::new();let mut out=vec![];for card in root.select(&sel(".article-card")){let Some(title)=card.select(&sel("h5.card-title")).next().map(|h|text_of(&h))else{continue};let Some(a)=card.select(&sel("a[href]")).next()else{continue};let Some(url)=a.value().attr("href").and_then(|h|common::link(base,h))else{continue};let u=Url::parse(&url)?;if u.origin()==base.origin()&&u.path().starts_with("/guidelines/clinical-practice-guidelines/")&&seen.insert(url.clone()){out.push((url,title))}}if out.is_empty(){bail!("ESC source guideline cards missing")};Ok(out)}
fn landing(raw:&str,base:&Url)->Result<(String,String,String,Vec<serde_json::Value>)>{let d=Html::parse_document(raw);let root=d.select(&sel("main")).next().context("ESC topic main missing")?;let title=root.select(&sel(".hero-intro h1")).next().map(|h|text_of(&h)).context("ESC topic title missing")?;let body=root.select(&sel(".container-fluid.bg-white .col-md-8")).next().context("ESC topic introduction missing")?;let notice=body.select(&sel("div.mt-5.fs-6")).find(|x|x.select(&sel("h4")).any(|h|text_of(&h)=="Copyright permission")).and_then(|x|x.select(&sel("p")).next().map(|p|text_of(&p))).context("ESC source copyright notice missing")?;let mut assets=vec![];for a in root.select(&sel("a[aria-label='Read the European Heart Journal'][href]")){if let Some(url)=a.value().attr("href").and_then(|h|common::link(base,h)){assets.push(json!({"url":url,"role":"full_journal_article","label":text_of(&a),"rights":"unknown; journal item independent"}));}}Ok((title,body.html(),notice,assets))}
fn issue(src:&SourceEntry,url:String,msg:String)->PlanRow{PlanRow{source_id:src.id.clone(),doc_key:format!("esc-{}-unresolved",common::short_hash(&url)),url,title:None,rendition:None,version:None,extra:json!({"discovery_error":msg})}}
#[async_trait::async_trait]
impl Adapter for Esc{async fn discover(&self,src:&SourceEntry,f:&Fetcher,limit:Option<usize>)->Result<Vec<PlanRow>>{if limit==Some(0){return Ok(vec![])}let c=f.get_ok(src.catalog_url.as_deref().unwrap_or(ROOT)).await?;let base=Url::parse(&c.record.final_url)?;if base.origin()!=Url::parse(ROOT)?.origin(){bail!("ESC catalog redirected outside source")};let entries=catalog(&c.text(),&base)?;let mut rows=cw::enumerate(src,f,"esc",limit,&HashSet::new()).await?;if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}let mut pmcids:HashSet<String>=rows.iter().filter_map(cw::row_pmcid).collect();for(url,_)in entries{let p=match f.get_ok(&url).await{Ok(p)=>p,Err(e)=>{rows.push(issue(src,url,format!("ESC topic unavailable: {e:#}")));if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}continue}};let u=Url::parse(&p.record.final_url)?;if u.origin()!=base.origin(){rows.push(issue(src,url,"ESC topic redirected outside source".into()));continue}let(title,body,notice,assets)=match landing(&p.text(),&u){Ok(v)=>v,Err(e)=>{rows.push(issue(src,url,format!("ESC topic template: {e:#}")));continue}};let h=crate::common::sha256_hex(serde_json::to_string(&(&title,&body,&notice,&assets))?.as_bytes());let year=title.split_whitespace().next().filter(|x|x.len()==4&&x.chars().all(|c|c.is_ascii_digit())).map(String::from);rows.push(PlanRow{source_id:src.id.clone(),doc_key:format!("esc-{}-{}",common::short_hash(&url),&h[..12]),url:url.clone(),title:Some(title.clone()),rendition:Some("html".into()),version:year,extra:json!({"snapshot":h,"role":"topic_preview"})});if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}for asset in &assets{let Some(target)=asset["url"].as_str()else{continue};
 // The overview's own journal link states the DOI; an Open Access PMC copy goes through the shared crosswalk.
 let mut crosswalk="no DOI stated by the overview link".to_string();
 if let Some(doi)=cw::doi_from_url(target){let sref=SourceRef{source_url:target.into(),evidence_url:Some(url.clone()),source_title:Some(title.clone()),item_type:Some("guideline".into()),key_prefix:"esc".into(),id_route:"source_doi".into(),notes:vec![format!("ESC overview page copyright notice (applies to ESC-hosted material; the PMC copy carries its own licence): {notice}")]};
  match cw::plan(src,f,Lookup::Doi(doi.clone()),sref,json!({"source_preview":url,"source_doi":doi})).await?{Planned::Open(row)=>{if !pmcids.insert(cw::row_pmcid(&row).unwrap_or_default()){continue}rows.push(row);if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}continue}Planned::Closed{reason,..}=>crosswalk=format!("DOI {doi}: {reason}")}}
 let err=match f.get_ok(target).await{Err(e)=>format!("ESC journal terminal unavailable: {e:#}; open-access crosswalk: {crosswalk}"),Ok(_)=>format!("ESC journal body returned bytes but full clinical template and item rights are unvalidated; open-access crosswalk: {crosswalk}")};let mut r=issue(src,target.into(),err);r.title=Some(title.clone());r.extra["source_preview"]=json!(url);rows.push(r);if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}}}Ok(rows)}
 async fn extract(&self,src:&SourceEntry,f:&Fetcher,row:&PlanRow)->Result<GuidelineDoc>{if cw::is_crosswalk_row(row){return cw::extract(src,f,row).await}if let Some(e)=row.extra["discovery_error"].as_str(){bail!("ESC discovery: {e}")};let p=f.get_ok(&row.url).await?;let u=Url::parse(&p.record.final_url)?;if u.origin()!=Url::parse(ROOT)?.origin(){bail!("ESC topic redirected outside source")};let(title,body,notice,assets)=landing(&p.text(),&u)?;let hash=crate::common::sha256_hex(serde_json::to_string(&(&title,&body,&notice,&assets))?.as_bytes());if row.extra["snapshot"].as_str()!=Some(hash.as_str()){bail!("ESC source preview changed; re-plan")};let(blocks,mut warnings)=blocks_from_html(&body,Some(&u),None);warnings.push("ESC source topic is an overview, not the full guideline or its recommendation set; linked publisher and assets require independent validation.".into());let rights=Rights{status:"restricted".into(),restrictions:vec![notice],evidence_urls:vec![row.url.clone()],note:Some("The publisher notice is kept as stated; journal and embedded asset rights are separate.".into()),..Default::default()};Ok(GuidelineDoc{source_id:src.id.clone(),doc_key:row.doc_key.clone(),work_key:Some(format!("esc-{}",common::short_hash(&row.url))),title,url:row.url.clone(),item_type:Some("guideline_overview".into()),version:row.version.clone(),status:"unknown".into(),rights,blocks,attachments:assets,fetches:vec![p.record],warnings,..Default::default()})}}
#[cfg(all(test, feature = "guideline-fixtures"))]mod tests{use super::*;const CAT:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/esc/catalog.html"));const AF:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/esc/af.html"));#[test]fn actual_af_preview_and_restricted_notice(){let rows=catalog(CAT,&Url::parse(ROOT).unwrap()).unwrap();let u="https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/";assert!(rows.iter().any(|(url,_)|url==u));let(title,body,notice,assets)=landing(AF,&Url::parse(u).unwrap()).unwrap();assert!(title.contains("2024")&&body.contains("AF-CARE"));assert!(notice.contains("No commercial use")&&notice.contains("formal license agreement")&&notice.contains("software tools"));assert!(assets.iter().any(|a|a["url"]=="https://academic.oup.com/eurheartj/article-lookup/doi/10.1093/eurheartj/ehae176"));}
 #[tokio::test]async fn actual_overview_is_separate_from_unavailable_article(){let u="https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/";let tmp=tempfile::tempdir().unwrap();let f=Fetcher::new(tmp.path(),true,500,1<<20,"").unwrap();f.seed_cache_for_tests(ROOT,CAT.as_bytes(),"text/html");f.seed_cache_for_tests(u,AF.as_bytes(),"text/html");let src:SourceEntry=serde_json::from_value(json!({"id":"esc","access":"public","enabled":true,"catalog_url":ROOT})).unwrap();let rows=Esc.discover(&src,&f,None).await.unwrap();let row=rows.iter().find(|r|r.url==u).unwrap();let d=Esc.extract(&src,&f,row).await.unwrap();assert_eq!(d.item_type.as_deref(),Some("guideline_overview"));assert_eq!(d.version.as_deref(),Some("2024"));assert_eq!(d.rights.status,"restricted");assert!(d.rights.restrictions[0].contains("formal license agreement"));assert!(rows.iter().any(|r|r.extra["source_preview"]==u&&r.extra["discovery_error"].is_string()));}
}
